import { activate_and_reactivate_expense_group } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    rowInfo: Object,
    deleteGroup: Boolean
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(activate_and_reactivate_expense_group, {
          expense_group_id: this.rowInfo.expense_group_id,
          expense_group_status: "DEACTIVE"
        }));
        var response = JSON.parse(result.data.activate_and_reactivate_expense_group);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message || "Failed to delete expense group");
        }
      } catch (error) {
        console.error("Error deleting expense group:", error);
        const errorMessage = error.errors && error.errors[0] ? error.errors[0].message : "Failed to delete expense group. Please try again.";
        this.$emit("errorMsg", errorMessage);
      } finally {
        this.loading = false;
      }
    }
  }
};
